insert into public.products (slug, title, updated, tagline, summary, image, sections, thin) values
('icm-integral-compact-multicyclone-spray-system', 'ICM – Integral Compact Multicyclone Spray System', '2025-12-26', 'Industrial automated powder lines where recovery and build quality matter.', 'The Integral Compact Multicyclone (ICM) stainless steel booth is designed for automatic powder coating and manual coating in multi-color operation. It stands out for its stable and robust construction. The stainless steel floor is accessible', null, null, true),
('id-spray-wall', 'ID Spray Wall', '2025-12-26', 'Ideal for smaller run parts, fixtures, and custom finishing jobs.', 'The ID spray wall is especially suitable for coating larger parts in single color operation or with frequent color changes. It convinces by its robust and scratch-resistant stainless steel floor.', '{"src":"/products/manual-booth-2.png","alt":"Spray Booth Wall for spray applications"}'::jsonb, null, true),
('imc-coatec-metering', 'IMC Coatec Metering', '2026-05-14', 'Coating Process meter mix equipment for in-mold coating of Sheet Molding Compound (SMC) utilized in automotive, commercial, recreational vehicle and FRP manufacturing.', 'IM Coatec (In Mold Coating Metering System) is used to provide a paintable, defect free, surface to molded parts made of fiber-reinforced plastics (FRP), or sheet molding compounds (SMC). Paintable surface upon exit of mold. “Class A” performance for In Mold Coating with IMCoatec Metering System. This dedicated system designed to give you a "Class A" finish with a minimum of expense, maintenance and hassle. Liquid, heat activated conductive in-mold coating is designed to enhance the surface of reinforced plastics, automotive, FRP truck body panels, or any molded part. In-Mold Coatings provide a smooth, protected, sealed surface that meets or exceeds most OEM coating specifications. They can be readily painted with standard automotive finishes using conventional or electrostatic equipment.', '{"src":"/products/IMC-Nozzle_May-6-2026.jpg","alt":"IMC Coatec Metering"}'::jsonb, '[{"heading":"Features:","items":["Material pressure vessel 24 l, cooled","Cooling circuit with cooling appliance","Lubrication circuit","Circulation pump","Pressure monitoring","Hydraulic volume metering unit (5 levels pressure control)","Hydraulic pressure control valve","10 m hose package with feed and return for: material, lubricant, coolant, hydraulic oil to control injection port","Cooled injection valve","Hydraulic aggregate with cooling appliance and pressure accumulator","Vacuum unit","Electronic control Vipa 315 usable by IPC","Interface 4 potential-free contacts","In Mold Coating on SMC in Automotive and Commercial Vechical Manufacturing","Fills the air spaces in the SMC (pore blocking)","Covers surface defects of the SMC surface","Covers the fiber of SMC","IMC creates a smooth surface to enable a class A surface"]}]'::jsonb, false),
('impulse-dosing-valve-idv', 'Impulse Dosing Valve (IDV)', '2026-03-04', 'SOMA IDV (Impulse Dosing Valve)', 'The SOMA IDV Impulse Dosing Valve is designed to precisely control the dosing of various fluids, particularly in industrial applications where accurate and reliable dosing is essential for product quality.', '{"src":"/products/img-impulse-dosing-valve1.jpg","alt":"Impulse Dosing Valve (IDV)"}'::jsonb, '[{"heading":"Features & Functionality","items":["Impulse Dosing: The IDV is capable of impulse dosing, which allows for precise and controlled delivery of fluids in small amounts.","Fast Switching: It features fast switching capabilities, enabling quick response times for dosing adjustments.","Compatibility: The IDV is compatible with a range of fluids, including lubricants, chemicals, and other industrial liquids.","Pressure Sensing: To ensure accuracy, it often incorporates pressure sensing technology to monitor and adjust dosing parameters in real-time.","Configurability: It can be configured and controlled through various means, such as digital interfaces and higher-level control units.","Teach Mode: The IDV often includes a \"teach mode,\" where operators can set and teach specific dosing parameters for different substances or applications."]},{"heading":"Applications","items":["Industrial Lubrication: In manufacturing settings, the SOMA IDV is commonly used for precise lubricant dosing in machinery, ensuring optimal performance and longevity.","Chemical Processing: It finds application in chemical dosing systems, where accurate dosing of chemicals is critical for reactions and product quality.","Food and Beverage: In food processing, the IDV can be used for controlled dosing of ingredients, flavors, and additives."]},{"heading":"Integration with Systems","items":["System Integration: The IDV is designed to seamlessly integrate into dosing systems, such as the SOMA DIS Dosing Inspection System mentioned earlier.","Control Options: It offers various control options, including integration with higher-level control units and digital interfaces for precise adjustments."]},{"heading":"Additional Components","items":["Valve Heating (SOMA IDV-H): This optional component provides heating to the IDV, which can be crucial for maintaining the proper viscosity of fluids in cold environments.","Dosing Piston Stroke Monitor (SOMA IDV-INI): Another optional component, this monitor helps in precisely measuring and controlling the stroke of the dosing piston for accurate dosing."]}]'::jsonb, false),
('light-barrier', 'Light Barrier', '2026-05-13', 'Peripherals', 'The light barrier is a process monitoring device used with the very fast-switching shot and high-speed valves. It counts the number of discharged shots, checking them against the set target quantity.', '{"src":"/products/Light_Barrier_03_24_2026.png","alt":"Light Barrier"}'::jsonb, null, true),
('low-pressure-impingement-mixing-valve', 'Low Pressure Impingement Mixing Valve', '2025-12-26', 'Impingement Mixing Valves for Urethane Foam & Elastomer: Enhancing Productivity', 'Welcome to Kirkco, your premier source for cutting-edge low-pressure impingement mixing valves designed to elevate productivity in filled and unfilled polyurethane applications. Our high-performance, low-pressure mixing heads lead the industry, featuring a precision tight-tolerance plunger design.', '{"src":"/products/image1.png","alt":"Low Pressure impingement mixing valve"}'::jsonb, '[{"heading":"Precision with Low Pressure Impingement Mixing Heads","paragraphs":["At the core of every foam processing unit, the mixing head assembly takes center stage. Engineered with precision, this crucial component ensures thorough mixing within the chamber, dispensing a precisely calibrated mixture through the nozzle outlet orifice. Kirkco manufactures four low-pressure mixing head sizes covering an output range from 1/4 to 400 lbs./min."]},{"heading":"Standard Low Pressure Mixing Head Assembly","paragraphs":["Crafted for Excellence","Our standard head assembly boasts robust construction, with major parts made from chrome-plated steel, Teflon-coated aluminum or stainless steel mixers, and Teflon or Viton seals. Key features include a mixing head body, bearing housing with high-speed bearings, a 4-way material valve, diaphragm-type flush valve, hardened mixer shaft, air-actuated valve operator, and an AC electric motor-driven mixer with variable speed."]},{"heading":"Tailoring to Your Needs: Low Pressure Mixing Head Upgrades","paragraphs":["Upgrade options abound for our mixing head assembly, including:"],"items":["Automatic Water Flush Module: Variable speed drive for mixer operation, enabling a speed range of 0 - 10,000 rpm, with automatic speed adjustment during cold water injection.","Water Cooled Addition: Ideal for non-stop operation, providing head cooling through a dual-wall bearing housing and mixer nozzle with cold water.","Automatic Color Selector: Effortless color changes for multi-component systems, enhancing operational flexibility.","Hydraulic Mixer Drive: Hydraulic motor-driven mixer with a speed of up to 10,000 rpm, offering the advantage of lower weight.","Static Mixer: Catering to specific elastomer systems, featuring a static mixer setup."]},{"heading":"Ensuring Seamless Operation: Double Hydraulic Solenoid Valve Control","paragraphs":["Equipped with a 7.5 kW hydraulic unit, pre-charged accumulator, pressure regulator, and integral heat exchanger, our low-pressure impingement mixing heads offer all the benefits of high-pressure metering technology. Whether in straight or L-style mix heads, expect smooth pouring, reduced costs, enhanced product quality, and the ability to use fast-reacting formulations."]}]'::jsonb, false),
('lsr-conti-mix-200', 'LSR Conti Mix 200', '2025-12-07', 'Metering & Mixing Plant for Liquid Silicone Rubber Applications', 'Two RAM units operate independently, in closed-loop control—economic and compact meter mix Plant for LSR processing. Dosing piston pumps, servo motor driven.', '{"src":"/products/Conti-Mix-200-LSR.jpg","alt":"LSR Conti Mix Industrial application dispensing with two drum pumps"}'::jsonb, '[{"heading":"Benefits of the LSR Conti Mix 200","items":["electrical driven","high precision","simultaneous drum emptying","compact design","energy saving","feeding system 20 l or 200 l","flow rate approx. 6 l/min"]},{"heading":"LSR Conti Mix 200 Applications / Uses","items":["textile coating","large volume e.g., insulators"]},{"heading":"LSR Conti Mix 200 Processing Unit","items":["Mixing unit without color","Mixing unit one color dosing valve","Mixing unit two color dosing valve","Mixer with water cooled jacket","Possible static mixer sizes","1/2 or 1 with 10 elements (standard)","1/2 or 1 with 20 elements","1/2 or 1 with 30 elements","8mm mixer for small shot volumes"]}]'::jsonb, false),
('lsr-20-ela-lsr-200-ela', 'LSR-20 ELA & LSR-200 ELA', '2025-12-07', 'Metering & Mixing Plant for Liquid Silicone Rubber Applications', null, '{"src":"/products/csm_LSR_200_ELA_ebc231e394.png","alt":"Liquid silicone rubber dispensing device for industrial applications"}'::jsonb, '[{"heading":"Benefits of the LSR-20 LC:","items":["all relevant information at a glance (pressure, fill level)","compact design","feeding system: 20 l"]},{"heading":"LSR Silicone Manufactures","items":["BlueStar Silicone","Wacker","Momentive","Dow Corning","ShinEtsu Silicones"]}]'::jsonb, false),
('lsr-20-lc', 'LSR-20 LC', '2025-12-07', 'Metering & Mixing Plant for Liquid Silicone Rubber Applications', 'Setup with a Pneumatic Drive Motor for reduced output 20L pail feeder. Economic and compact meter mix Plant for LSR processing. Dosing piston pumps pneumatic driven', '{"src":"/products/RT-LSR-Machines.jpg","alt":"Liquid silicone rubber dispensing device for industrial applications"}'::jsonb, '[{"heading":"Benefits of the LSR-20 LC","items":["economic version","compact design","feeding system: 20 l"]},{"heading":"LSR Silicone Manufactures","items":["BlueStar Silicone","Wacker","Momentive","Dow Corning","ShinEtsu Silicones"]}]'::jsonb, false),
('m-cube', 'M-Cube', '2025-12-26', 'High-mix and multi-product automated spray environments.', 'The M-Cube plastic booth is configured according to customer specifications. A quick color change is possible due to the PVC sandwich design. Due to their modular design, the manual coating platforms can be placed individually for pre and/or post coating. The plastic floor is accessible.', null, null, true),
('material-filter', 'Material Filter', '2025-12-24', 'Material Filters for Clean, Consistent Flow in Lubrication Systems', 'A material filter is an inline device designed to remove particulate contaminants from grease, oil, and other lubricant fluids before they reach sensitive downstream components like flow meters, metering valves, and dispensing systems. By capturing debris and solid contaminants, material filters help protect system components, stabilize flow, and extend the service life of lubrication equipment. In lubrication and fluid delivery systems, filtration is a critical step in flow regulation — keeping materials clean ensures more reliable flow measurement, fewer blockages, and reduced maintenance.', '{"src":"/products/800_800_image_291978_31178467_d7778d0c64b6ba21494c97f77a66885a.png","alt":"Material Filters with connectors"}'::jsonb, '[{"heading":"Inline Lubricant Filter Assembly","paragraphs":["A compact, inline filter designed to capture solid contaminants from lubricant supply lines. Installed upstream of flow meters and regulating valves, it protects sensitive components and smooths overall fluid delivery."]},{"heading":"Key Features:","paragraphs":["Stainless steel or corrosion-resistant construction","Replaceable filter elements with varying micron ratings","Integrated bypass or relief paths to prevent pressure buildup","Compatible with greases, oils, and industrial lubricants","Easy element replacement for minimal downtime"]},{"heading":"Benefits:","paragraphs":["Protects downstream metering valves and sensors","Reduces maintenance frequency and cost","Helps maintain a consistent flow rate"]},{"heading":"Ideal For:","paragraphs":["Centralized lubrication systems","Pump feed lines to metering and dispensing valves","Industrial lubrication circuits with particulate risk"]},{"heading":"High-Capacity Industrial Filter Units","paragraphs":["Designed for higher flow rates and heavier industrial use, high-capacity material filters provide larger surface area and longer element life — reducing replacement frequency in busy lubrication systems."]},{"heading":"Key Features:","paragraphs":["Larger filter media surface for extended life","Multiple micron ratings to match material types","Heavy-duty housing for industrial environments","Optional sight glass or indicators for clog monitoring"]},{"heading":"Benefits:","paragraphs":["Supports larger feed lines and higher throughput","Improves uptime with longer service intervals","Handles heavier contamination loads"]},{"heading":"Ideal For:","paragraphs":["High-volume lubrication distribution networks","Automated production environments","Systems serving multiple lubrication points"]},{"heading":"How Material Filters Integrate in Flow Regulation","paragraphs":["Material filters are typically installed upstream of flow meters and flow regulating valves. A typical integration path might look like: Pump Supply → Material Filter → Flow Meter → Flow Regulating Valve → Metering/Dispensing Valve","This arrangement ensures:"],"items":["Only clean lubricant reaches precision measurement and control devices","Reduced risk of clogging or erratic readings","Extended service life of moving and sealing components"]},{"heading":"Common Industrial Applications","paragraphs":["Material filters are used widely where lubricant cleanliness directly affects performance, including:","By removing particles before they reach sensitive equipment, material filters help ensure stable flow performance and cleaner lubrication delivery."],"items":["Automated assembly line lubrication","Centralized lubrication systems with multiple branch lines","Machine tool lubrication feed lines","Maintenance and service stations requiring consistent flow quality","Any system feeding expensive metering valves or precision components"]}]'::jsonb, false),
('material-fluid-pressure-regulator', 'Material Fluid Pressure Regulator', '2025-12-24', 'Material Fluid Pressure Regulators for Consistent and Controlled Lubricant Delivery', 'Material fluid pressure regulators are engineered components used in lubrication and fluid delivery systems to reduce and stabilize the pressure of pumped material. They ensure that grease, oil, and other lubricants are delivered at a controlled, consistent pressure — even when upstream pump conditions fluctuate — which helps achieve repeatable performance from metering valves, dispensing devices, and lubrication points. Pressure regulation is essential in applications where changes in pump output could otherwise lead to inconsistent lubricant feed, excess force on downstream components, or variations in dosing accuracy.', '{"src":"/products/material_fluid_pressure.png","alt":"Material Fluid Pressure regulation device"}'::jsonb, '[{"heading":"Why Pressure Regulation Matters","paragraphs":["Without a material fluid pressure regulator, variations in pump output pressure (such as pulsations from reciprocating pumps or changes due to system backpressure) can lead to:","A properly regulated lubrication system improves repeatability, system stability, and service life of pumps and valves."],"items":["Inconsistent feed rates","Erratic metering valve performance","Excessive wear or premature component failure","Material surges that compromise lubrication precision"]},{"heading":"Common Performance Characteristics","paragraphs":["Pressure regulators from Kirkco are designed to deliver:","These regulators can be configured with multiple pressure setpoints based on application demands and material viscosity."],"items":["Stable outlet pressure even with upstream fluctuations","Reduced pulsation effects, contributing to smoother downstream flow","Improved metering accuracy and repeatability","Extended service life for metering and dispensing valves","Wide compatibility with greases, oils, and industrial lubricant types"]},{"heading":"Piston‑Type Material Fluid Pressure Regulator","paragraphs":["A robust regulator using a piston mechanism to maintain a stable outlet pressure for grease, oil, and other lubricants. Designed for industrial environments where steady pressure is critical for feeding metering valves and dispensing systems."]},{"heading":"Key Features:","items":["Pneumatic or spring‑balanced piston design","Maintains a stable set pressure downstream","Low maintenance, high durability","Handles medium to high pressures","Suitable for grease, oil, and similar fluid media"]},{"heading":"Ideal For:","items":["Central lubrication systems","Metrology‑critical dispense applications","Feed to metering/dispensing valves"]},{"heading":"Diaphragm‑Type Material Fluid Pressure Regulator","paragraphs":["A regulator utilizing a diaphragm seal to isolate the spring and control chamber from the material path. This design is ideal for sensitive or abrasive fluids, including greases with fillers or fluids sensitive to contamination."]},{"heading":"Key Features:","items":["Diaphragm isolation protects control components","Resistant to abrasive and reactive materials","Good chemical compatibility for diverse lubricants","Smooth, stable pressure output","Easy adjustment and serviceability"]},{"heading":"Ideal For:","items":["Abrasive or filled grease applications","Silicones, polyurethanes, and specialty lubricants","Systems where material‑friendly designs are required"]},{"heading":"Typical Industrial Applications","paragraphs":["Material fluid pressure regulators are used in systems where precision lubricant delivery and stable pressure are essential, including:","Automated assembly applications demanding repeatable feed","By stabilizing pressure and reducing pulsation, these regulators help optimize system performance and reduce wear on pumps, valves, and delivery components."],"items":["Automated lubrication networks in manufacturing facilities","Centralized grease and oil distribution systems","High‑accuracy metering and dispensing stations","Maintenance and machine tool lubrication"]},{"heading":"Why Choose Kirkco Pressure Regulators","paragraphs":["Kirkco’s material fluid pressure regulators are engineered for industrial reliability, robust performance, and compatibility with a wide range of lubrication materials. They integrate seamlessly with:","This makes them a powerful component in comprehensive lubrication solutions."],"items":["Pumps (low, medium, and high pressure)","Metering valves","Electronic metering and control systems","Centralized lubrication networks"]}]'::jsonb, false),
('medium-pressure-pumps', 'Medium Pressure Pumps', '2026-05-04', 'Reliable Medium-Pressure Lubrication Pumps for Grease & Oil Delivery', 'Kirkco medium-pressure lubrication pumps are designed to deliver consistent feed of greases, oils, and lubricants at pressures that bridge basic low-pressure supply and high-pressure metering systems. These pumps are ideal for applications that require controlled pressure and continuous flow, such as feeding metering valves, lubrication manifolds, and centralized lubrication systems in industrial environments.', '{"src":"/products/PCP-Pump-image.png","alt":"Medium Pressure Pumps"}'::jsonb, '[{"heading":"Key Features:","items":["Pneumatic operation for industrial safety and reliability","Smooth fluid output at controlled medium pressure","Handles a broad range of grease and oil viscosities","Self-priming and dry-run capable","Simple maintenance and long service life"]},{"heading":"Applications:","items":["Feed to metering valves and dispenser points","Conveyor and production line lubrication","Centralized system feed for moderate distances or pressure requirements"]},{"heading":"Key Features:","items":["Reciprocating piston for reliable, repeatable feed","Smooth medium-pressure capability for moderate lubrication networks","Compatible with both greases and oils","Built for extended duty cycles","Can feed multiple lubrication points from a single source"]},{"heading":"Applications:","items":["Feeding metering valves in manufacturing lines","Workshop lubrication stations","Machine tool applications requiring medium-pressure feed"]},{"heading":"Key Features:","items":["Medium-pressure feed from pails, drums, and bulk containers","Reduces air entrainment and material separation","Pneumatic or optional hydraulic actuation","Uniform flow into metering or dispensing equipment"]},{"heading":"Applications:","items":["Drum-mounted medium-pressure supply systems","Feeding valve clusters or distributor blocks","Centralized lubrication system integration"]}]'::jsonb, false),
('micro-mix', 'Micro Mix', '2025-12-10', 'DOPAG MICRO-MIX® piston type shot metering and mixing system:', 'MICRO-MIX® is ideal for processing low, medium, and high viscosity, filled, or abrasive materials. The range of applications for this system consists mainly of the “shot-type” dispensing of minute quantities of evenly mixed material. All polymers, e.g., polyurethanes, silicones, and epoxy resins, can be processed using this system. The three main units that make up this group of positive displacement shot metering and mixing systems are the Micro Mix E, Micro Mix S, and the Micro Mix K.', '{"src":"/products/micro-mix-kapkf82.jpg","alt":"Micro Mix device"}'::jsonb, '[{"heading":"MICRO-MIX E","paragraphs":["MICRO-MIX E® has two piston type metering pumps driven by a pneumatic air cylinder and lever system assembly. We set the mixing ratio by changing the lever system and the shot size is a mechanical stop. The mixing ratio is adjustable within the given range of the selected metering pump combination. Variable ratios of 1:1 to 10:1 are the most common. Mix ratios outside of this range are possible in some situations."],"images":[{"src":"/products/micro-mix-efpkf82.jpg"}]},{"heading":"MICRO-MIX S","paragraphs":["MICRO-MIX S® is equipped with two piston type metering pumps driven via a stepper motor. The material is applied either in shot form for precise and accurate dots or continuously for precise beads. This unit is also equipped with a variable adjustable mixing ratio. The main benefit of the MICRO-MIX S metering and mixing system is the integral MR-20 metering computer.","The MR-20 metering computer is used in automated production applications and has multiple programmable shot capabilities and many additional features and options including:"],"items":["Material pressure monitoring","Material level monitoring","Pot Life alarms","Production monitoring"]}]'::jsonb, false),
('micro-flow-sensor', 'Micro-flow Sensor', '2026-05-13', 'Peripherals', 'The micro-flow sensor can be used with needle metering valves to confirm that material is being dispensed. It is designed for the detection of very small quantities (0.005 – 3.00 ml). This device is meant purely for material discharge monitoring purposes, not as a means of volumetric measurement.', '{"src":"/products/Micro-Flow-Sensor_03_24_2026.jpg","alt":"Micro-flow Sensor"}'::jsonb, null, true),
('modular-pump-systems', 'Modular Pump Systems', '2026-05-24', 'Modular Lubrication Pump Systems for Flexible Grease & Oil Delivery', 'Kirkco modular pump systems provide scalable lubrication feed solutions capable of handling a wide range of grease, oil, and lubricant transfer needs. These systems combine multiple pump types, reservoirs, control elements, and accessories into configurable packages that can be tailored to your plant’s specific lubrication requirements — from small automated lines to centralized systems serving many lubrication points.', '{"src":"/products/PailPump_30Lt.jpg","alt":"Modular Pump Systems"}'::jsonb, '[{"heading":"Key Features:","items":["Integrated low- and high-pressure stages for flexible lubrication feed","Pneumatic or air-operated power options","Pumps compatible with greases and oils across viscosity ranges","Expandable with pressure regulators, sensors, and accessories","Ideal for centralized systems and shuttle feed networks"]},{"heading":"Applications:","items":["Centralized lubrication installations","Automated production lines requiring dual-pressure feed","Multi-zone lubrication distribution"]},{"heading":"Key Features:","items":["Redundant pump modules for continuous reliability","Automatic or manual transfer to backup unit","Modular components for easy servicing and expansion","Compatible with system monitoring and alerts"]},{"heading":"Applications:","items":["High-availability manufacturing environments","Mission-critical lubrication systems","Facilities where downtime is extremely costly"]},{"heading":"Key Features:","items":["Multiple pumps integrated into a central frame","Independent pressure or flow control for each zone","Compatible with metering valves, regulators, and sensors","Scalable to support additional zones"]},{"heading":"Applications:","items":["Large manufacturing cells with multiple lubrication zones","Central lubrication for industrial complexes","Systems feeding diverse lubrication requirements from one centralized rack"]}]'::jsonb, false),
('mr40-metering-control-unit', 'MR40 Metering Control Unit', '2026-05-13', 'Connect and control your metering components', 'The MR40 is a control unit developed by KIRKCO for the control of complex metering processes. It can be easily integrated into a system with a metering valve or into a 1K metering system with dispensing valves. The control unit enables communication between individual system components and coordinates their operation. Additionally, the featured software allows users to store numerous metering programs and to recall and run them later. The control unit is equipped with connection ports for various material supply systems and is compatible with monitoring devices such as the gear flow meter or the light barrier. It can be used either as system control or as an interface between a higher level system control and a metering system.', '{"src":"/products/MR_Enclosure_03_24-2026.jpg","alt":"MR40 Metering Control Unit"}'::jsonb, null, true),
('needle-dispensing-valve', 'Needle Dispensing Valve', '2026-04-30', 'Continuous dispensing with great flexibility', 'Based on the time-pressure dispensing principle, the needle dispensing valves are most effective in continuous applications of low to high viscosity media. Consisting of two structurally separate parts, they have the advantage that material cannot leak into the drive cylinder and interfere with the valve needle movement. The size of the orifice is regulated by stroke adjustment knurled nut. A special, adjustable seal closes the valve needle off from the valve head, ensuring a perfectly clean and precise application of every single shot. The material passageway can be flushed when necessary.', '{"src":"/products/Needle-Dispensing-Valve-Robot-Dispense1.jpg","alt":"Needle Dispensing Valve"}'::jsonb, '[{"heading":"Needle Dispensing Valve Features and Options","items":["Continuous Application (Time-Pressure Dispensing)","Internal Diameter 1, 2.5, 6 And 12 Mm","Max. Input Pressure 250 Bar","Compatible With Stroke Detection","Sealing Available In Various Sizes And Material Finishes","Option - Solenoid Valve Plate 24 V","Option - Signal Generator With Various Cables","Option - Various Adapters And Needle Tips","Option - Pneumatic Or Electric Handle"]}]'::jsonb, false),
('needle-metering-valve', 'Needle Metering Valve', '2025-12-11', 'Needle Metering Valve', 'Kirkco uses Needle Metering Valves for processing low to high viscosity medias. Example: Positive Displacement Needle Metering Valve The valve consists of two separate parts, a fluid section and a pneumatic section. This separation reduces the chance for leaking material to flow into the actuating air cylinder that might cause a malfunction of the valve. The needle is sealed by means of adjustable packing set. Speed of metering depends on the material viscosity and the material pressure.', '{"src":"/products/Metering_Valves_2.jpg","alt":"Needle Metering devices for dispensing industrial application"}'::jsonb, '[{"heading":"Needle Metering Valve Features and Benefits","items":["Wetted parts made of stainless steel","Metering volume infinitely adjustable within the appropriate shot range","Valve seat and valve needle made of hardened alloy for processing abrasive media","High-precision, reproducible dosage of very small volumes","Handle for electric or pneumatic control"]}]'::jsonb, false),
('piston-pumps', 'Piston Pumps', '2025-12-22', 'Engineered Piston Pump Technology for Single-Component Adhesives & Sealants', 'Kirkco offers a complete range of single-component pneumatic piston pumps , spanning from compact to high-volume models such as Wildcat, Puma, Leopard, Jaguar, and Tiger. These pumps deliver precise volumetric flow per double stroke for reliable supply, transfer, and dispense of adhesives, sealants, and other single-component materials across industrial applications', '{"src":"/products/ice-breaker-air-motor.jpg","alt":"Piston air pump for dispensing"}'::jsonb, '[{"heading":"Pneumatic Piston Pump Operation","paragraphs":["Pneumatic piston pumps are powered by an air motor that alternately drives a piston up and down to draw material from a container and deliver it under pressure. During the up stroke, material enters the fluid section; during the down stroke, it displaces material into the pressure line — generating consistent output for spray guns or dispensing systems."]},{"heading":"Design Features & User Benefits","paragraphs":["Engineered for industrial use, all piston pump fluid sections are constructed with stainless steel components, large replaceable inlet/outlet valves, and integral pressure regulation. Key practical advantages include:"],"items":["Low pulsation for smoother spray and reduced finish variability","Easy-to-maintain fluid section with quick access to service parts","Air motor with IceBreaker technology to minimize icing during operation","Precise material pressure control via pump ratio and air pressure settings","Long-term reliability with a three-year warranty (excludes wear parts)"]},{"heading":"Low vs. High Pressure Piston Pumps","paragraphs":["Kirkco piston pumps are available in configurations that balance flow rate and working pressure for specific processes:"],"items":["Low-Pressure Pumps: High volumetric flow at lower working pressures — ideal for material transport and supply systems.","High-Pressure Pumps: Lower flow with elevated pressures — suitable for direct application in Airless, AirCoat, and electrostatic spray operations."]},{"heading":"IceBreaker Air Motor Advantage","paragraphs":["The industry-proven IceBreaker air motor design significantly reduces internal icing — eliminating frequent work interruptions for thawing. This also enhances performance with:"],"items":["Integrated pressure regulation","Pneumatic control without the need for oil","Low pulsation for smoother material flow","Compact, ergonomic housing for industrial environments"]},{"heading":"Packings","paragraphs":["Packings are seals that seal the piston from the piston guide. Packings can either be static, which means they are permanently attached, or dynamic, in which case they move with the piston.","The material used for packings should be chosen in accordance with the material being processed. One of Kirkco''s technical specialists can assist by providing more information."]},{"heading":"Thermo Technology","paragraphs":["We Offer the Best!","Piston pumps with explosion protected inline fluid heater Wagner Thermo technology combines the tried-and-tested pneumatic piston pumps Puma 28-40 and Leopard 35-70 with an explosion-protected inline fluid heater. This guarantees a constant paint temperature with a maximum outlet temperature of 65 ° C and a maximum working temperature of 80 ° C. This temperature control of the sprayed material reduces its viscosity, achieving better atomisation and quicker degassing. The drying times are reduced, the process characteristics improved, and a homogeneous, smooth surface is achieved. Not only furniture manufacturers (wear-proofing), window makers, and carpentry and joinery firms benefit from Thermotechnik, but it is also used in heavy steelwork, shipbuilding, and plastics processing (e.g., for car accessories)."],"items":["Tiger 72-300","Jaguar 38-300","Jaguar 75-150","Leopard 18-300","Leopard 35-150","Leopard 35-70","Puma 15-150","Puma 28-40","Puma 15-70","Wildcat 18-40","Wildcat 10-70"]},{"heading":"Pneumatic Pump Spray Packages","paragraphs":["Kirkco covers the entire spectrum of pneumatic spray pump packages used in industrial and contracting protective coating and spray finishing applications. Whether Air-Assisted, AirCoat, Airless or electrostatic, mobile or stationary – Kirkco can provide a comprehensive spray package solution.","Lets Find a Pneumatic Pump Spray Package For you! WAGNER AIR-OPERATED PISTON PUMPS AIRLESS & AIR-ASSISTED PACKAGES:","Applicators"],"items":["Tiger 72-300","Jaguar 38-300","Jaguar 75-150","Leopard 18-300","Leopard 35-150","Leopard 35-70","Puma 15-150","Puma 28-40","Puma 15-70","Wildcat 18-40","Wildcat 10-70","AirCoat guns","Airless guns","Electrostatic guns","Base stand"]}]'::jsonb, false),
('pressure-sensors', 'Pressure Sensors', '2026-05-24', 'Pressure Sensors for Adhesive & Sealant Dispensing', 'Pressure sensors play a critical role in monitoring and verifying material conditions within adhesive and sealant dispensing systems. These devices measure real-time material pressure at key points in the dispensing process and provide feedback to process control computers, monitoring systems, and automation platforms. Within Kirkco’s Process & Control architecture, pressure sensors function as part of the Monitoring & Analytics layer, supplying essential data that supports consistent dispensing performance, system diagnostics, and closed-loop control. Compatible with: Shot Valves Spray Valves Integration into a system (digital / analogue)', '{"src":"/products/Pressure-Regulators.jpg","alt":"Pressure Sensors"}'::jsonb, null, true),
('pressure-vessels', 'Pressure Vessels', '2026-04-30', 'Industrial Pressure Vessel Solutions for Single-Component Material Delivery and Storage', 'Kirkco pressure vessels provide robust material storage and controlled delivery for single-component adhesives, sealants, and pourable materials. Built to industrial standards, these tanks support consistent feed to pumps, metering systems, and dispensing equipment with safe, regulated pressure.', '{"src":"/products/Bulk-Stainless-Steel-Tank_03_24-2026_.jpg","alt":"Pressure Vessels"}'::jsonb, '[{"heading":"Small Tanks","images":[{"src":"/products/small-tanksnpm482.gif"}]},{"heading":"Large Tanks","images":[{"src":"/products/large-tanksrpm482.gif"}]},{"heading":"Material Circulation Systems","images":[{"src":"/products/circulation-systems-03j8of82.gif"},{"src":"/products/circulation-systems-01enn482.gif"},{"src":"/products/circulation-systems-02inn482.gif"}]},{"heading":"Accessory Items","paragraphs":["Oscillation Sensor: Various sizes available Get Help Finding The Right Accessories For Your Paint Application"],"items":["Capacitive Filling","Level Indicator","Various sizes available"],"images":[{"src":"/products/filling-level-indicatorsf7n482.gif"}]}]'::jsonb, false),
('progressive-cavity-valves', 'Progressive Cavity Valves', '2025-12-17', 'Continuous metering with the highest accuracy', 'The progressive cavity pump is a high-precision volumetric metering system that operates continuously and pulsation-free. The rotational motion of the eccentric screw ensures highly precise, constant metering, particularly in the case of small output rates from 0.1 ml/min. The special rotor-stator combination prevents excessive wear when processing abrasive materials. This guarantees a long service life and high cost-efficiency.', '{"src":"/products/csm_ContiPro_f1c929a713-1.png","alt":"Progressive Cavity Valves"}'::jsonb, '[{"heading":"Progressive Cavity Valve Features and Options","items":["Variable discharge rate from 0.002 ml","Output rate of 0.1 to 45 ml/min","Speed of 0 to 150 rev/min","Maximum input pressure of 6 bar","Maximum operating pressure of 10 bar","Ideally suitable for all viscosities from highly fluid to pasty","Snuff-back function","Option - Cartridge supply 10cc / 30cc / 55cc","Option - Pressure regulator and level control for cartridge supply","Option - Spray adaptor","Option - Servo controller","Option - Various needle tip"]}]'::jsonb, false),
('protec-2k-mixing-dosing-unit', 'PROTEC 2K Mixing & Dosing Unit', '2025-12-26', null, 'The PROTEC 2K Mixing & Dosing Unit is specifically engineered for heavy-duty corrosion protection applications involving highly filled, two-component protective coatings. It provides both precise metering of individual components and reliable, thorough mixing — ensuring uniform material delivery even under demanding conditions.', '{"src":"/products/Picture4.jpg","alt":"Dosing and Mixing unit on a custom portable dolly"}'::jsonb, null, true),
('pump-packages', 'Pump Packages', '2025-12-24', 'Complete Lubrication Pump Packages for Grease, Oil & Fluid Feed Solutions', 'Kirkco pump packages are pre-engineered lubrication feed systems combining pumps, reservoirs, controls, and accessories into unified solutions tailored for grease, oil, and lubricant delivery. These packages simplify system design, reduce installation time, and ensure a consistent, dependable supply from drums, pails, cartridges, or bulk tanks to downstream metering or dispensing equipment. Pump packages are ideal for facilities that require standardized, configurable systems that support maintenance, manufacturing, or automated lubrication points without custom engineering from scratch.', null, '[{"heading":"High-Pressure Pump Package","paragraphs":["This package integrates a high-pressure pump stage to support heavier lubrication drives, feeding metering valves, distribution manifolds, or systems requiring elevated operating pressure for proper delivery."]},{"heading":"Key Features:","items":["Pump selected for elevated pressure ranges","Strong performance with greases and thicker oils","Includes regulators and dampeners for stable pressure","Designed for robust industrial environments","Easy integration with control panels"]},{"heading":"Applications:","items":["High-pressure lubrication networks","Centralized metering valve feed","Heavy equipment lubrication systems"]},{"heading":"Medium-Pressure Pump Package","paragraphs":["A package engineered for controlled medium-pressure feed, balancing flow and pressure for applications that don’t require a dedicated high-pressure system but need more than a simple low-pressure pump."]},{"heading":"Key Features:","items":["Delivers reliable medium-pressure feed","Works with a broad range of lubricant viscosities","Includes optimized pressure control components","Modular design for accessories"]},{"heading":"Applications:","items":["Conveyor and line lubrication","Machinery lubrication","Multi-zone feed systems"]},{"heading":"Dual-Stage Pump Package","paragraphs":["Combines two pump stages (e.g., low and medium or low and high pressure) into one integrated package for flexible feed requirements — ideal when feeding both bulk supply and downstream metering simultaneously."]},{"heading":"Key Features:","items":["Two pump stages in one compact system","Pneumatic or powered configurations available","Integrated pressure control for each stage","Expandable with sensors and filtration"]},{"heading":"Applications:","items":["Large manufacturing cells with multiple lubrication zones","Central lubrication for industrial complexes","Systems feeding diverse lubrication requirements from one centralized rack"]}]'::jsonb, false),
('rim-mix', 'RIM MIX', '2026-05-13', 'Polyurethane Processing Equipment', 'High Pressure mixing unit for filled materials Rim-Mix Series production of parts with mechanical strength where a fiber is mixed with the polyol (especially in the automotive sector) production where a high resistance to fire is required by adding graphite in powder or microspheres (rigid and flexible foam as well) productions where a substantial cost reduction is required (addition of fillers that increase the weight of the part produced)', '{"src":"/products/RIM_MIX_04_01_2026.png","alt":"RIM MIX"}'::jsonb, null, true),
('shot-valves', 'Shot Dispensing Valves', '2026-09-19', 'Lubrication of hard-to-reach places in automated processes', 'Shot valves are extremely fast-switching valves designed for the application of grease and oil from distance (contactless) in automated processes. They are capable of dispensing the smallest amounts of material at the speed of up to 200 cycles per second. This is possible thanks to the integrated 5/2 way solenoid valve (also used for control), together with short paths in the entire air supply system. The valves are available with both short and long nozzles, which enables them to cover various angles of application. Depending on the nozzle size, media with different viscosities can be processed easily.', '{"src":"/products/C1_glamor.jpg","alt":"Shot Dispensing Valves"}'::jsonb, '[{"heading":"Shot Valves Dispensing Valve Features and Options","items":["Shot application","Nozzle size ⌀ 0.2 – 1.0 mm","Input pressure max. 100 bar","24 V DC solenoid valve for maximum shot frequency","200 Hz SHV-01 / 30 Hz SHV-02","Option - Stroke detection device with cable","Option - Nozzle extensions with various lengths and shot angles","Option - 24 V / 50 W heating with temperature sensor PT100","Option - Pressure sensor","Option - Light barrier for shot detection","Option - Rotary applicator"]}]'::jsonb, false),
('silco-mix', 'Silco Mix', '2025-12-07', 'Dopag Silco-Mix Piston Type Metering and Mixing', 'SILCO-MIX is a special system for transferring, metering and mixing liquid silicone rubbers (LSR) from the original 5 gallon (20 liter) pails or 55 gallon (200 liter) drums. Models: SILCO-MIX P SILCO-MIX PH SILCO-MIX H SILCO-MIX V', '{"src":"/products/silco-mix-04dprg92.gif","alt":"Silco Mix Industrial application dispensing"}'::jsonb, '[{"paragraphs":["SILCO-MIX P is an entry-level system for silicone processing. The metering pumps are operated pneumatically via a lever system. SILCO-MIX PH is a pneumatic / hydraulic hybrid system and works with a fixed mixing ratio. A patented process ensures high metering accuracy by absolute synchronicity of the metering pumps.","SILCO-MIX H is a version of the system in which the metering pumps are operated hydraulically. The system is especially used for processing high viscosity media.","The SILCO-MIX V (VOLU-MIX design) uses low viscosity silicones to manufacture small components with a batch weight of up to approximately 150 grams and continually monitors a variable mixing ratio.","All systems of the SILCO-MIX series work without flushing agents."],"images":[{"src":"/products/silco-mix-02w5nf82.gif"}]},{"heading":"Silco Mix Special Features","items":["Pneumatic, Hydraulic or Pneumatic/ Hydraulic Hybrid driven","Fixed mixing ratio of 1:1","Viscosities up to 4,000,000 cps / 30 – 90 Shore","Output up to 2.5 liters per minute, depending on viscosity","Exact metering accuracy","Material level controls","Simple operation","Low maintenance","Precise color injection 0.2 – 5 % in dependence of the output flow rate"]}]'::jsonb, false),
('spray-valves', 'Spray Valves', '2025-12-24', 'Full surface coverage applied from a distance', 'The spray valve is a special kind of valve designed for full-surface application of greases and oils. It is suitable for both intermittent and continuous material applications. A unique feature of this valve is the integration of a membrane, which is used for the adjustment of the air blow duration after each material shot - this serves the cleaning of the nozzle. Short airways in the body of the valve and a flange-mounted 5/2 way solenoid valve allow a very fast and accurate intermittent operation. A wide range of available extensions and attachments open up the possibility of spray application in hard-to-access areas, while various aircaps allow the customization of the spray coating pattern.', '{"src":"/products/spray-valve.jpg","alt":"Spray valve application for spraying internal items"}'::jsonb, null, true),
('spray-wall-basic-8000', 'Spray Wall Basic 8000', '2025-12-26', 'Manual coating of structural parts, small runs, and job-shop tasks.', 'The Basic 8000 Spray Wall is a manual spray environment tailored to larger parts and cost-effective operations. It’s equipped with essential performance functions for industrial spray finishes and can be integrated with manual conveyor systems or handling fixtures.', '{"src":"/products/manual-booth-1.png","alt":"Spray Booth Wall for spray applications"}'::jsonb, null, true),
('static-mixer-system', 'Static Mixer System', '2025-12-10', 'Kirkco''s Solventless Static Mixer System', 'Kirkco''s innovative metering and mixing system features a solventless design for components A and B. These components are meticulously fed separately up to the dispense valve, utilizing specialized valve stems and nozzles equipped with check valves. The valve stems are engineered to exert a snuff back effect upon closing, effectively preventing any undesired dripping from the static mixer tube outlet. Notably, the snuff effect is fully adjustable using a convenient knurled screw.', null, '[{"heading":"Plastic Static Mixer","paragraphs":["The system incorporates a plastic static mixer designed for the homogeneous blending of two-component materials. In this process, the materials are individually fed until they converge at the inlet edge of the mixer. The mixer''s helical spirals within the mix tube play a crucial role, continuously dividing the material flow and seamlessly blending the two components. The layout of these spirals generates a rotary effect, ensuring a radially homogeneous mix of the components.","Importantly, the two components remain distinct until entering the mixer, guaranteeing that homogeneous mixing occurs precisely at that juncture. The mixed material is then dispensed with a carefully controlled snuff effect upon closure, preventing any residual dripping. This snuffer effect is fully customizable through the use of a user-friendly knurled knob. Remarkably, the entire process is achieved without the need for solvent flushing, emphasizing the system''s efficiency and environmental consciousness."]}]'::jsonb, false),
('stroke-detection', 'Stroke Detection', '2026-05-13', 'Peripherals', 'The stroke detection device monitors the correct activity of various valve types. Detecting the upstroke movement of the dispensing needle or the metering piston, it sends signals to indicate the proper functioning of a valve.', '{"src":"/products/Stroke_detection_03_24_2026.png","alt":"Stroke Detection"}'::jsonb, null, true),
('super-cube', 'Super Cube', '2025-12-26', 'Automated powder coating where flexibility and changeovers are needed', 'The Super Cube plastic booth is configured according to customer specifications. Robot and axis technology can be integrated and the use of the PVC elements allows a fast color change. Due to their modular design, the manual coating platforms can be placed individually for pre and/or post coating. The plastic floor is accessible.', null, null, true),
('transfer-pump', 'Transfer Pump', '2025-12-22', 'KIRKCO’s Transfer pumps for direct supply from original container', 'The Best solution for the control and transfer of liquids, fluids, and pastes. Facilitates precise transfer from storage tanks to blending or metering systems. Equipped with variable speed drives for sensitive handling of temperature and flow fluctuations. Depending on the application type, it may be useful to be able to supply material directly from the original containers using a transfer pump. Kirkco offers double-acting transfer pumps with fast-switching airmotors. It should be noted that the use of transfer pumps is always dependent on the material properties and the container type.', '{"src":"/products/TransferPump1.png","alt":"Transfer pump diagram"}'::jsonb, null, true),
('twincontrol-2k-mixing-dosing-unit', 'TWINCONTROL 2K Mixing & Dosing Unit', '2025-12-26', null, 'The TWINCONTROL 2K is a highly portable and cost-effective mixing/dosing unit designed for a wide range of protective coating applications, especially those involving highly viscous materials at high flow rates. Its compact design makes it easy to deploy across job sites or production floors.', '{"src":"/products/Picture5.jpg","alt":"Dosing and Mixing unit on a custom portable dolly"}'::jsonb, null, true),
('ultramix', 'ULTRAMIX', '2025-12-26', 'Polyurethane Processing Equipment', 'The High Pressure foaming machine Ultramix Series provides great flexibility for medium to high productions using multiple mixing heads with flow rates from 5 to 5000 gr / sec. It''s very useful in sectors where variable shot to shot ratios are required (automotive for example). Production of integral self-skinning parts, flexible dual-hardness productions, and productions where it is necessary to produce with variable flow rates in general (self-regulation of the flow rates) full-optional equipment included in the price.', '{"src":"/products/ULTRAMIX.jpg","alt":"Ultra mix device for industrial applications"}'::jsonb, null, true),
('ultramix-10-s-micro-dosing', 'ULTRAMIX 10-S MICRO DOSING', '2025-12-10', 'Polyurethane Processing Equipment', 'ULTRAMIX 10.S High pressure micro dosing In the last few years ISC has successfully dedicated itself to “micro dosing” polyurethane in high pressure, pouring up to one gram through a “L” type self-cleaning mixing-head. ISC has manufactured several machines which satisfy the needs of different sectors such as naval industry, railway industry, automotive industry, furniture and medical industry. The machine named ULTRAMIX 10-S is sometimes connected to a Robot, manual working centers or CNC automatic centers. Precision makes the difference @ ISC.', '{"src":"/products/MICRO-DOSING.jpg","alt":"Ultra mix micro dosing"}'::jsonb, null, true),
('ultramix-p', 'ULTRAMIX P', '2025-12-10', 'Polyurethane Processing Equipment', 'High Pressure foaming machines for hydrocarbons-blown systems Ultramix/P Series productions with dangerous and flammable blowing agents production of refrigerators and chest freezers in the household appliances sector production of blast chillers, commercial refrigerators, cold rooms in the commercial and industrial sector sandwich panels for the building sector special productions of integral self-skinning foams standard equipment of integrated safety systems and monitoring of explosive gas leaks The “Ultramix/P” is the high-pressure metering machine designed for the safe use of flammable blowing agents, such as Cyclopentane, Isobutane, etc. Submitted to a complete and accurate risk analysis, hydrocarbons-blown systems can be considered safe and pose no danger to the operators involved in the process or to the environment. The need to reduce the environmental impact from greenhouse emissions policy of our company has the key point development, pushing ISC S.r.l. to design a foaming machine helping those foam with hydrocarbons to sustainable development. However, choosing a machine for PU foaming with Pentane is always a very important choice, The experience of the SC S.r.l. has developed this series of foaming machines for making the only choice,', '{"src":"/products/ULTRAMIX-P.jpg","alt":"Ultramix dispensing material glass container"}'::jsonb, '[{"heading":"Features with a very high standard as:","items":["300 liters jacketed tanks with capacitive level and agitator,","Axial piston dosing pumps with magnetic coupling, filter in suction and digital safety pressure gauges,","Flowmeters with \"close-loop\" function integrated in the PLC. Electric control panel realized according to the customer needs. Possibility to manage multiple mixing heads for high production needs and working recipes up to 99 (standard solution c/w 12 recipes),","The electric panel of the foaming machine is supplied along a monitoring panel for ventilation and gas detectors control","The monitoring panel can handle not only the foaming machine safeties but also other parts of the line (Jigs, Presses and Premix stations),","The Polyol/C-pentane part of the machine is located under forced ventilation with continuous monitoring , All the sensible parts, where required, are supplied with Atex certification and other parts follow CE markings standards,","The ULTRAMIX-P series can be easily installed on existing plants even \"stand-alone\"","Possibility of revamping of existing machines with low investment impact","Solutions with more than two components according the application to use."]}]'::jsonb, false),
('ultramix-plus', 'ULTRAMIX PLUS', '2025-12-10', 'Polyurethane Processing Equipment', 'Multicomponent High Pressure foaming machines for continuous sandwich panel lines Ultramix Plus Series foaming machines dedicated to the production of sandwich panels production of dedicated or combined PUR and PIR foams very high productivity and great flexibility usually combined with foaming portal use of hydrocarbons in almost all applications', '{"src":"/products/ULTRAMIX-PLUS.jpg","alt":"Ultramix plus"}'::jsonb, null, true),
('vario-mix', 'Vario Mix', '2025-12-07', 'DOPAG VARIO-MIX® Piston Type Metering and Mixing', 'The VARIO-MIX® is suitable for use with low to medium high viscosity materials whether they are filled, abrasive, or neither. The VARIO-MIX system can process practically all multi-component polymers and adhesives.', '{"src":"/products/lamination1.jpg","alt":"Vario mix show in 4 angles"}'::jsonb, '[{"heading":"Vario-Mix A","paragraphs":["Used for medium to large continuous material output applications such as casting, coating and gluing. The VARIO-MIX A1/A2 uses positive displacement reciprocating metering pumps and drives them by either a pneumatic or hydraulic power supply system attached to an adjustable lever system assembly. The mixing ratio is adjustable within the given range of the selected metering pump combination via a knurled knob. Variable ratios of 1:1 to 20:1 are most common. Mix ratios outside of this range are possible in some situations."],"images":[{"src":"/products/vario-mix.jpg"}]},{"heading":"Vario-Mix S","paragraphs":["Used for shot dispense applications and is particularly suitable if the material is being processed in larger quantities by hand or in conjunction with an automated system. The VARIO-MIX S1/S2 is available in both pneumatic and hydraulic versions and operates using positive displacement shot metering pumps.","Mix ratio, shot size and cycle speed are designed into the system during configuration. Shot size selection can be from a mechanical or electronic selector or from an onboard MR-20 processing computer or PLC."],"images":[{"src":"/products/VM1A-with-pail-supply.jpg"}]},{"heading":"Vario-Mix L (Lamination)","paragraphs":["The VARIO-MIX L is an amended design for supplying lamination systems with continuously metered, mixed, and monitored material. This type of system is principally used in the intermittent production and multi-shift operations of the laminated plastics and foil industry.","It operates in the same manner as the VARIO-MIX A with the added features of auto tank refilling, system and material heating and real time close looped monitoring of the material as it is being processed.","All configurations of the VARIO-MIX are standard as “SOLVENT FREE” which means they work as standard without a flushing agent by using disposable static mixers. A version with a low flushing agent requirement is available for special applications if required.","Get a Quote For Vario-Mix L"]}]'::jsonb, false),
('vecdos-eone', 'Vecdos eOne', '2025-12-11', 'Positive Displacement Metering Valves', 'The Vecdos eOne series of servo driven high-performance metering units is the ideal solution for any intermittent single component metering application. The volumetric shot metering units are modular and flexible in combinations for different metering requirements. The design is optimal for difficult and abrasive materials and available for smallest shot volumes. The smart metering control provides unmatched reliable and repeatable precision in your metering application. Servo controlled volumetric dosing units for precise and repeatable adhesive and sealant application in automated lines.', '{"src":"/products/VecdosEOne_.png","alt":"Shot needle metering device"}'::jsonb, null, true),
('vecdos-etwin', 'Vecdos eTwin', '2025-12-22', 'Servo Driven High Performance Metering Unit', 'The Vecdos eTwin series of servo driven high-performance metering units is the ideal solution for any intermittent two component metering application. The volumetric shot metering units are modular and flexible in combinations for different mixing ratios. The design is optimal for difficult and abrasive materials and available for smallest shot volumes. The smart metering control provides unmatched reliable and repeatable precision in your metering application. Servo controlled volumetric dosing units for precise and repeatable adhesive and sealant application in automated lines.', '{"src":"/products/Electrical-dozer-with-feeding-units.jpg","alt":"Vecdos eTwin Device for dispensing application"}'::jsonb, '[{"heading":"Vecdos eOne Benefits and Options","items":["Innovative solutions help to save material, increase productivity, and enhance sustainability","Robust 1K and 2K processing equipment for reliable operation in demanding production environments","Smart metering control","Zero-backlash screw & servo drive","Compact & low weight","Robust design","Option - Dynamic Mixer","Option - Static Mixer","Option - Satellite Version: For Robot Mounting","Option - Hydraulic Drive: For Highest Pressure Requirements"]}]'::jsonb, false),
('volume-counter', 'Volume Counter', '2025-12-24', 'Volume Counters for Accurate Lubricant Tracking & Flow Verification', 'A volume counter is a device that tracks the cumulative total volume of fluid moving through a lubrication or fluid delivery system. By capturing totalizer readings based on pulses from a flow meter or gear sensor, a volume counter helps operators verify usage, monitor system performance, and support maintenance planning. In lubrication systems, this means accurate records of grease or oil delivered, whether for quality control, preventive maintenance, or inventory tracking.', '{"src":"/products/electronically-Flow-Meter-Exp1bnv92.gif","alt":"Flow Meter Expanded to see inside the device"}'::jsonb, '[{"heading":"Digital Volume Counter","paragraphs":["A digital counter that displays the totalized volume of lubricant delivered based on signals from flow monitoring devices. Ideal for systems where accuracy, ease of reading, and data tracking are important."]},{"heading":"Key Features:","paragraphs":["Digital display with cumulative total reading","Compatible with pulse outputs from flow meters","High-resolution counting for precise records","Reset or non-resettable options per system needs","Easy mounting near application points or operator stations"]},{"heading":"Benefits:","paragraphs":["Clear real-time usage tracking","Supports maintenance planning and documentation","Improves transparency in automated lubrication systems"]},{"heading":"Ideal For:","paragraphs":["Industrial and centralized lubrication networks","Production lines with usage verification requirements","Quality tracking and reporting environments"]},{"heading":"Mechanical Volume Counter","paragraphs":["A rugged, mechanical totalizer designed for harsh environments where simplicity and durability are priorities. Works with compatible flow sensors or gear meters to accumulate volume based on mechanical pulses."]},{"heading":"Key Features:","paragraphs":["Durable mechanical gearing for robust operation","Analog totalizer dial with high readability","Works with pulse signals from compatible meters","No external power required for basic models"]},{"heading":"Benefits:","paragraphs":["Reliable in environments with electrical limitations","Easy to service and maintain","Clear cumulative usage readout"]},{"heading":"Ideal For:","paragraphs":["Heavy equipment lubrication systems","Remote or non-powered installations","Centralized feed systems where visual verification is preferred"]},{"heading":"Common Industrial Applications","paragraphs":["Volume counters are widely used in systems where lubricant tracking and usage reporting are essential, including:","By capturing accurate usage information, volume counters help teams optimize lubricant inventory, reduce waste, and support proactive servicing."],"items":["Centralized lubrication networks feeding multiple points","Automated assembly lines requiring documented flow control","Machine tool lubrication with verified dispense volumes","Maintenance workshop stations needing consumption logs","Quality assurance environments requiring usage records"]},{"heading":"Why Choose Kirkco Volume Counters","paragraphs":["Kirkco’s volume counter solutions are engineered to deliver:","When combined with flow meters, filters, and flow regulating valves, volume counters help build a comprehensive flow regulation strategy that supports performance, documentation, and process optimization."],"items":["Reliable tracking of grease, oil, and fluid flow","Compatibility with flow meters and sensors used in industrial lubrication systems","Durable performance in factory and workshop conditions","Flexible display options (digital or mechanical) to match site needs"]}]'::jsonb, false);